/* 
  A Resilient Fetch function that handles Rate Limits 
*/

async function fetchWithRetry(url) {
  const response = await fetch(url);

  if (response.status === 429) {
    // We got blocked! Read the header to see how long we are in timeout.
    // (e.g., "60" means wait 60 seconds)
    const retryAfter = response.headers.get('Retry-After');
    const waitTime = retryAfter ? parseInt(retryAfter) * 1000 : 5000;

    console.warn(`Rate limited! Pausing script for ${waitTime}ms...`);

    // Pause the JavaScript thread
    await new Promise(resolve => setTimeout(resolve, waitTime));

    // Try the exact same request again!
    return fetchWithRetry(url);
  }

  return response.json();
}
